                _ => null,
              },
            )

(_, s) {
              final typeName = s.uri.queryParameters['type'];
              NoticeType? preset;
              if (typeName != null) {
                for (final t in NoticeType.values) {
                  if (t.name == typeName) {
                    preset = t;
                    break;
                  }
                }
              }
              return NoticePublishPage(
                presetType: preset,
                presetSubjectId: s.uri.queryParameters['subject'],
              );
            }

